import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Laravel Fortify Auth with 2FA & Passkeys","description":"Fortify-based authentication with separate central and tenant guards, two-factor codes, passkeys and per-domain toggles for each sign-in feature.","frontmatter":{"title":"Laravel Fortify Auth with 2FA & Passkeys","description":"Fortify-based authentication with separate central and tenant guards, two-factor codes, passkeys and per-domain toggles for each sign-in feature.","head":[["link",{"rel":"canonical","href":"https://saas-laravel.com/docs/core/authentication.html"}],["meta",{"property":"og:title","content":"Laravel Fortify Auth with 2FA & Passkeys"}],["meta",{"property":"og:description","content":"Fortify-based authentication with separate central and tenant guards, two-factor codes, passkeys and per-domain toggles for each sign-in feature."}],["meta",{"property":"og:url","content":"https://saas-laravel.com/docs/core/authentication.html"}],["meta",{"name":"twitter:title","content":"Laravel Fortify Auth with 2FA & Passkeys"}],["meta",{"name":"twitter:description","content":"Fortify-based authentication with separate central and tenant guards, two-factor codes, passkeys and per-domain toggles for each sign-in feature."}]]},"headers":[],"relativePath":"docs/core/authentication.md","filePath":"docs/core/authentication.md","lastUpdated":1790486087000}'),o={name:"docs/core/authentication.md"};function d(r,e,n,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h1><p>Authentication is powered by <strong>Laravel Fortify</strong> (headless) with Inertia pages. Fortify handles the routes and logic; the <code>Modules/Auth</code> module connects it to the kit&#39;s pages, actions and rate limits.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Fortify feature</th><th>Pages</th></tr></thead><tbody><tr><td>Login / logout</td><td>always on</td><td><code>auth/Login</code></td></tr><tr><td>Registration</td><td><code>Features::registration()</code></td><td><code>auth/Register</code></td></tr><tr><td>Password reset</td><td><code>Features::resetPasswords()</code></td><td><code>auth/ForgotPassword</code>, <code>auth/ResetPassword</code></td></tr><tr><td>Email verification</td><td><code>Features::emailVerification()</code></td><td><code>auth/VerifyEmail</code></td></tr><tr><td>Password confirmation</td><td>always on</td><td><code>auth/ConfirmPassword</code></td></tr><tr><td>Two-factor auth (TOTP + recovery codes)</td><td><code>Features::twoFactorAuthentication()</code></td><td><code>auth/TwoFactorChallenge</code>, Security settings</td></tr><tr><td>Passkeys (WebAuthn)</td><td><code>Features::passkeys()</code></td><td>Login, Confirm password, Security settings</td></tr></tbody></table><p>Page names are shown in Vue/Svelte casing; React uses kebab-case (<code>auth/two-factor-challenge</code>).</p><p>Signed-in users also get these settings pages:</p><table tabindex="0"><thead><tr><th>Page</th><th>URL</th><th>Contains</th></tr></thead><tbody><tr><td>Profile</td><td><code>/settings/profile</code></td><td>Name, email, language, delete account</td></tr><tr><td>Security</td><td><code>/settings/security</code> (requires password confirmation)</td><td>Change password, 2FA, passkeys</td></tr><tr><td>Appearance</td><td><code>/settings/appearance</code></td><td>Light, dark, system</td></tr><tr><td>Layout</td><td><code>/settings/layout</code></td><td>Personal layout options</td></tr></tbody></table><h2 id="how-it-is-wired" tabindex="-1">How it is wired <a class="header-anchor" href="#how-it-is-wired" aria-label="Permalink to &quot;How it is wired&quot;">​</a></h2><p><code>AuthServiceProvider</code> in the Auth module tells Fortify which actions and Inertia pages to use, and registers the rate limiters. On tenant domains it also points Fortify at the <code>tenant</code> guard, so users are logged into the right database.</p><table tabindex="0"><thead><tr><th>Rate limiter</th><th>Limit</th></tr></thead><tbody><tr><td><code>login</code></td><td>5 per minute per email + IP</td></tr><tr><td><code>two-factor</code></td><td>5 per minute per login session</td></tr><tr><td><code>passkeys</code></td><td>10 per minute per credential (or session) + IP</td></tr></tbody></table><p><strong>Related files</strong></p><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>Modules/Auth/Providers/AuthServiceProvider.php</code></td><td>Fortify actions and views, rate limiters, <code>StatefulGuard</code> binding</td></tr><tr><td><code>Modules/Auth/Actions/CreateNewUser.php</code>, <code>ResetUserPassword.php</code></td><td>Registration and password reset</td></tr><tr><td><code>config/fortify.php</code></td><td><code>home</code> is <code>/dashboard</code>; the full feature list</td></tr><tr><td><code>app/Models/User.php</code></td><td>Uses <code>TwoFactorAuthenticatable</code>, <code>PasskeyAuthenticatable</code>, <code>HasRoles</code></td></tr></tbody></table><h2 id="central-and-tenant-guards" tabindex="-1">Central and tenant guards <a class="header-anchor" href="#central-and-tenant-guards" aria-label="Permalink to &quot;Central and tenant guards&quot;">​</a></h2><p>Central users and tenant users live in different databases, so each context has its own session guard. Both guards use the same <code>App\\Models\\User</code> model.</p><table tabindex="0"><thead><tr><th>Guard</th><th>Provider and password broker</th><th>Database</th></tr></thead><tbody><tr><td><code>web</code></td><td><code>central_users</code></td><td>Central</td></tr><tr><td><code>tenant</code></td><td><code>tenant_users</code></td><td>Tenant</td></tr></tbody></table><p>You never switch guards by hand. On every request the kit sets the Laravel and Fortify guard for the current context, and the <code>auth</code> / <code>guest</code> middleware aliases map <code>web</code> to <code>tenant</code> inside a tenant. Write <code>-&gt;middleware(&#39;auth&#39;)</code> in both contexts.</p><div class="info custom-block"><p class="custom-block-title">Separate accounts</p><p>A central user and a tenant user are different records in different databases, even with the same email. Sessions are also per host.</p></div><p><strong>Related files</strong>: <code>config/auth.php</code>, <code>App\\Http\\Middleware\\InitializeTenancyIfTenantDomain</code>, <code>App\\Listeners\\ConfigureTenantAuth</code>, <code>App\\Listeners\\RevertTenantAuth</code>. See <a href="/docs/core/architecture.html#central-vs-tenant-context">Architecture → Central vs tenant context</a>.</p><h2 id="per-domain-features" tabindex="-1">Per-domain features <a class="header-anchor" href="#per-domain-features" aria-label="Permalink to &quot;Per-domain features&quot;">​</a></h2><p>Each tenant domain can turn Fortify features off without code changes, for example to disable self-registration for one customer. Open <strong>Tenants → Domains → Authentication features</strong>; the dialog lists every feature from <code>config/fortify.php</code> with a toggle.</p><p>How it works:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>domains.auth_features (JSON)   → stored per domain; missing keys count as enabled</span></span>
<span class="line"><span>tenancy starts                 → ApplyTenantFortifyFeatures filters fortify.features</span></span>
<span class="line"><span>request to a disabled feature  → EnsureTenantAuthFeatureEnabled returns 404</span></span></code></pre></div><p>Blocked route names include <code>register</code>, <code>password.request</code>, <code>verification.*</code>, <code>two-factor.*</code> and <code>passkey.*</code>.</p><p>The central domain always uses the full <code>config/fortify.php</code> list. To disable a feature everywhere, remove it from that list.</p><h2 id="registration-and-permissions" tabindex="-1">Registration and permissions <a class="header-anchor" href="#registration-and-permissions" aria-label="Permalink to &quot;Registration and permissions&quot;">​</a></h2><p><code>CreateNewUser</code> creates a user <strong>without a role or permissions</strong>. Fortify then redirects to <code>/dashboard</code>, which requires <code>View Analytics Dashboard</code> (central) or <code>View Tenant Dashboard</code> (tenant).</p><div class="warning custom-block"><p class="custom-block-title">New users see a 403</p><p>A freshly registered user gets a <strong>403</strong> on the dashboard until an admin assigns a role.</p></div><p>Your options:</p><ul><li>Assign a role in <code>Modules\\Auth\\Actions\\CreateNewUser::create()</code> (below). <code>RoleEnum::USER</code> has no dashboard permission by default, so pick a role, or edit <code>config/permissions/*.php</code>, to fit your app.</li><li>Turn registration off per domain (see above).</li></ul><details class="details custom-block"><summary>View implementation example</summary><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">use</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Modules\\RolePermission\\Enums\\RoleEnum</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">use</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Modules\\RolePermission\\Services\\PermissionService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$user </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> User</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">create</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PermissionService</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">assignRole</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($user, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">RoleEnum</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">USER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">value);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $user;</span></span></code></pre></div></details><h2 id="email-verification" tabindex="-1">Email verification <a class="header-anchor" href="#email-verification" aria-label="Permalink to &quot;Email verification&quot;">​</a></h2><p><code>Features::emailVerification()</code> is enabled, but <code>App\\Models\\User</code> does <strong>not</strong> implement <code>MustVerifyEmail</code> (the import is commented out). The <code>verified</code> middleware therefore lets unverified users through.</p><p>To require verification, uncomment the <code>MustVerifyEmail</code> import in <code>app/Models/User.php</code> and add it to the class:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> User</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> extends</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Authenticatable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> implements</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MustVerifyEmail</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PasskeyUser</span></span></code></pre></div><p>Seeded users are already verified, and invited users are verified when they accept.</p><h2 id="passwords" tabindex="-1">Passwords <a class="header-anchor" href="#passwords" aria-label="Permalink to &quot;Passwords&quot;">​</a></h2><p><code>AppServiceProvider</code> sets <code>Password::defaults()</code>:</p><table tabindex="0"><thead><tr><th>Environment</th><th>Rules</th></tr></thead><tbody><tr><td>Production</td><td>At least 12 characters, mixed case, letters, numbers, symbols, not in known breaches</td></tr><tr><td>Other</td><td>Laravel&#39;s default rules</td></tr></tbody></table><h2 id="passkeys" tabindex="-1">Passkeys <a class="header-anchor" href="#passkeys" aria-label="Permalink to &quot;Passkeys&quot;">​</a></h2><p>Passkeys use <code>@laravel/passkeys</code> on the frontend and Fortify&#39;s passkey routes.</p><table tabindex="0"><thead><tr><th>Setting (<code>config/fortify.php</code>)</th><th>Value</th></tr></thead><tbody><tr><td>Relying party ID</td><td>Host of <code>APP_URL</code></td></tr><tr><td>Allowed origin</td><td><code>APP_URL</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Use HTTPS locally</p><p>Browsers only allow WebAuthn on secure origins. Run <code>herd secure</code> to test passkeys.</p></div><h2 id="invitations" tabindex="-1">Invitations <a class="header-anchor" href="#invitations" aria-label="Permalink to &quot;Invitations&quot;">​</a></h2><p>Two invitation flows let admins create accounts without choosing a password:</p><ul><li><strong>Tenant admin invitation</strong>: see <a href="/docs/core/multi-tenancy.html#invitations">Multi-tenancy</a>.</li><li><strong>User invitation</strong>: see <a href="/docs/core/users-roles-permissions.html#invitations">Users, roles &amp; permissions</a>.</li></ul><p>Both send queued emails with a signed link valid for 7 days; run a <a href="/docs/getting-started/local-development.html#queue-worker">queue worker</a>.</p>`,46)])])}const g=t(o,[["render",d]]);export{u as __pageData,g as default};
